import{_ as a,o,c as t,a5 as d}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"右移","description":"在计算机科学中，将一个数右移一位的操作通常被称为逻辑右移或算术右移，具体取决于处理的是无符号数还是有符号数。在大多数编程语言中，对整数进行右移操作意味着将该数的二进制表示向右移动指定的位数，相当于除以2的指定次幂。对于无符号数，这通常是逻辑右移，对于有符号数，这是算术右移。 逻辑。","frontmatter":{"title":"右移","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"在计算机科学中，将一个数右移一位的操作通常被称为逻辑右移或算术右移，具体取决于处理的是无符号数还是有符号数。在大多数编程语言中，对整数进行右移操作意味着将该数的二进制表示向右移动指定的位数，相当于除以2的指定次幂。对于无符号数，这通常是逻辑右移，对于有符号数，这是算术右移。 逻辑。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/JD5 字符个数统计/右移.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/JD5 字符个数统计/右移.md","filePath":"posts/前端面试与实战/03-算法训练/JD5 字符个数统计/右移.md"}'),c={name:"posts/前端面试与实战/03-算法训练/JD5 字符个数统计/右移.md"};function r(s,e,i,l,n,p){return o(),t("div",null,[...e[0]||(e[0]=[d('<div><h1 id="右移" tabindex="-1">右移 <a class="header-anchor" href="#右移" aria-label="Permalink to &quot;右移&quot;">​</a></h1><blockquote><p>本节目标：理解“右移”的核心思路，并能把它用于实际开发或面试表达。 在计算机科学中，将一个数右移一位的操作通常被称为逻辑右移或算术右移，具体取决于处理的是无符号数还是有符号数。在大多数编程语言中，对整数进行右移操作意味着将该数的二进制表示向右移动指定的位数，相当于除以2的指定次幂。对于无符号数，这通常是逻辑右移，对于有符号数，这是算术右移。</p></blockquote><h3 id="逻辑右移" tabindex="-1">逻辑右移 <a class="header-anchor" href="#逻辑右移" aria-label="Permalink to &quot;逻辑右移&quot;">​</a></h3><p>逻辑右移（<code>\\&gt;\\&gt;\\&gt;</code>在某些语言中）是指将数字的二进制表示向右移动，并在左边空出的位上填充0。逻辑右移不考虑数字的符号位，始终在左侧填充0。</p><h3 id="算术右移" tabindex="-1">算术右移 <a class="header-anchor" href="#算术右移" aria-label="Permalink to &quot;算术右移&quot;">​</a></h3><p>算术右移（<code>\\&gt;\\&gt;</code>在大多数编程语言中）也是将数字的二进制表示向右移动，但是填充空出的最左边的位时会考虑原始数的符号。对于正数，在左侧填充0；对于负数，在左侧填充1。这样做是为了保持负数的符号位不变。</p><h3 id="右移的意义" tabindex="-1">右移的意义 <a class="header-anchor" href="#右移的意义" aria-label="Permalink to &quot;右移的意义&quot;">​</a></h3><p>右移一位通常意味着将数字除以2，例如：</p><ul><li>如果有一个整数<code>10</code>，其二进制表示为<code>1010</code>，右移一位后变为<code>0101</code>，等于<code>5</code>。</li><li>如果有一个整数<code>-10</code>（假设使用8位二进制表示，为有符号整数），其二进制表示可能为<code>11110110</code>，右移一位后变为<code>11111011</code>（注意符号位为1，表示这是一个负数），这仍然保持了其为负数的特性。</li></ul></div>',1)])])}const u=a(c,[["render",r]]);export{_ as __pageData,u as default};
